 with open('/app/dataset/'+name+'.csv') as f: rows=list(csv.DictReader(f))
 print('\nFILE',name,'COUNT',len(rows))
 if name!='timesheet':
  for r in rows: print(r)
 else:
  for k in rows[0]:
   ct=collections.Counter(r[k] for r in rows)
   print(k, 'unique',len(ct),'missing',ct.get(''), 'min/max',min(ct),max(ct))
   if k in ['employee_id','hours_worked','facility_id']:
    print(ct)
  print('duplicate ids',[(k,v) for k,v in collections.Counter(r['id'] for r in rows).items() if v>1])
  print('duplicate employee/date',[(k,v) for k,v in collections.Counter((r['employee_id'],r['date']) for r in rows).items() if v>1])
PY","max_output_tokens":10000}));

