"""Calculate monthly cleaning-service payroll from the supplied CSV files."""

import ast
import csv
import json
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(name):
    with (DATASET / name).open(encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def _task_ids(value):
    """Repair missing outer brackets without guessing any task identifiers."""
    value = value.strip()
    if not value.startswith("["):
        value = "[" + value
    if not value.endswith("]"):
        value += "]"
    try:
        parsed = ast.literal_eval(value)
    except (ValueError, SyntaxError):
        return []
    if not isinstance(parsed, list):
        return []
    return [task_id for task_id in parsed if type(task_id) is int]


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"].strip(): Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    task_rates = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }

    records = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        # Duplicate shifts were assigned different record IDs.
        signature = tuple((key, value) for key, value in row.items() if key != "id")
        if signature in seen:
            continue
        seen.add(signature)

        pesel = row["employee_id"].strip()
        if pesel not in employees:
            # No reliable employee identity or hourly rate is available.
            continue
        try:
            worked_on = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, InvalidOperation):
            # Impossible dates cannot be assigned to a shift reliably.
            continue
        if not hours.is_finite() or not Decimal(0) <= hours <= Decimal(24):
            continue
        records.append((pesel, worked_on, hours, _task_ids(row["performed_tasks"])))

    if not records:
        return {pesel: [] for pesel in employees}

    billing_weekday = min(record[1] for record in records).weekday()

    def billing_month(worked_on):
        first = worked_on.replace(day=1)
        start = first + timedelta(days=(billing_weekday - first.weekday()) % 7)
        if worked_on < start:
            worked_on = first - timedelta(days=1)
        return worked_on.year * 12 + worked_on.month - 1

    totals = defaultdict(Decimal)
    months = set()
    for pesel, worked_on, hours, task_ids in records:
        month = billing_month(worked_on)
        months.add(month)
        # Use task definitions to correct inconsistent bonuses. Unlisted tasks
        # have no verifiable rate and are excluded from the bonus calculation.
        bonus = sum((task_rates.get(task_id, Decimal(0)) for task_id in task_ids), Decimal(0))
        totals[pesel, month] += hours * employees[pesel] + bonus

    # salary_amount is a running hourly-pay balance, as verified against the
    # cleaned shifts; summing that column would count hours repeatedly.
    ordered_months = range(min(months), max(months) + 1)
    return {
        pesel: [
            int(totals[pesel, month].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
        for pesel in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as handle:
        json.dump(answer(), handle, default=list)
